class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        for i in range(n):
            for j in range(i + 1, n):
                set_i = set(properties[i])
                set_j = set(properties[j])
                common = len(set_i & set_j)
                if common >= k:
                    x_root = find(i)
                    y_root = find(j)
                    if x_root != y_root:
                        if rank[x_root] < rank[y_root]:
                            parent[x_root] = y_root
                        else:
                            parent[y_root] = x_root
                            if rank[x_root] == rank[y_root]:
                                rank[x_root] += 1

        roots = set()
        for x in range(n):
            roots.add(find(x))

        return len(roots)
```

